def create_app():
    app = Flask(__name__)

    @app.route('/webhook', methods=['POST'])
    def webhook():
        req = request.get_json(silent=True, force=True)
        print("Request:")
        print(json.dumps(req, indent=4))

        # Decide which backend to call
        if req.get("result", {}).get("action") == "yahooWeatherForecast":
            response = _yahoo_backend(req)
        else:
            response = _soap_backend(req)

        return jsonify(response)

    def _build_yql_query(req):
        city = req.get("result", {}).get("parameters", {}).get("geo-city")
        if not city:
            return None
        return ("select * from weather.forecast where woeid in "
                "(select woeid from geo.places(1) where text='" + city + "')and u='c'")

    def _format_yahoo_response(data):
        query = data.get('query')
        if not query:
            return {}
        result = query.get('results')
        if not result:
            return {}
        channel = result.get('channel')
        if not channel:
            return {}
        item = channel.get('item')
        location = channel.get('location')
        units = channel.get('units')
        if not all([location, item, units]):
            return {}
        condition = item.get('condition')
        if not condition:
            return {}
        speech = ("Aujourd hui a " + location.get('city') +
                  ", la temperature est de " + condition.get('temp') +
                  " " + units.get('temperature'))
        print("Response:")
        print(speech)
        return {
            "speech": speech,
            "displayText": speech,
            "source": "apiai-weather-webhook-sample"
        }

    def _yahoo_backend(req):
        yql_query = _build_yql_query(req)
        if not yql_query:
            return {}
        baseurl = "https://query.yahooapis.com/v1/public/yql?"
        yql_url = baseurl + urllib.urlencode({'q': yql_query}) + "&format=json"
        result = urllib.urlopen(yql_url).read()
        data = json.loads(result)
        return _format_yahoo_response(data)

    def _soap_backend(req):
        url = "https://signets-ens.etsmtl.ca/Secure/WebServices/SignetsMobile.asmx"
        querystring = {"op":"echo"}
        payload = ("<?xml version=\"1.0\" encoding=\"utf-8\"?>\n"
                   "<soap12:Envelope xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" "
                   "xmlns:xsd=\"http://www.w3.org/2001/XMLSchema\" "
                   "xmlns:soap12=\"http://www.w3.org/2003/05/soap-envelope\">\n"
                   "<soap12:Body>\n"
                   "<infoEtudiant xmlns=\"http://etsmtl.ca/\">\n"
                   "<codeAccesUniversel>AN61920</codeAccesUniversel>\n"
                   "<motPasse>Englishman31</motPasse>\n"
                   "</infoEtudiant>\n"
                   "</soap12:Body>\n"
                   "</soap12:Envelope>")
        headers = {
            'content-type': "application/xml",
            'cache-control': "no-cache",
            'postman-token': "454669d8-db0e-a32c-1cd4-fd8908180f60"
        }
        response = requests.post(url, data=payload, headers=headers, params=querystring)
        print("Response:")
        print(response.text)
        return {
            "speech": response.text,
            "displayText": response.text,
            "source": "apiai-weather-webhook-sample"
        }

    return app


