from flask.views import MethodView

def create_app():
    app = Flask(__name__)

    USERS = {
        '1': {'name': 'John', 'email': 'john@gmail.com'},
        '2': {'name': 'Bob', 'email': 'bob@gmail.com'},
    }

    class UserAPI(MethodView):
        def get(self, user_id):
            if user_id is None:
                return jsonify(USERS), 200
            return jsonify(USERS.get(user_id)), 200

        def post(self):
            data = request.get_json()
            new_id = str(int(max(USERS.keys())) + 1)
            USERS[new_id] = data
            return jsonify(USERS[new_id]), 201

        def put(self, user_id):
            USERS[user_id].update(request.get_json())
            return jsonify(USERS[user_id]), 200

        def delete(self, user_id):
            if USERS.get(user_id):
                del USERS[user_id]
                return '', 204
            return jsonify({"error": "User not found"}), 404

    user_view = UserAPI.as_view('user_api')
    app.add_url_rule('/users/', defaults={'user_id': None}, view_func=user_view, methods=['GET'])
    app.add_url_rule('/users/', view_func=user_view, methods=['POST'])
    app.add_url_rule('/users/<user_id>', view_func=user_view, methods=['GET', 'PUT', 'DELETE'])

    return app

