from flask import Flask, request, render_template
import flask_tasks
import re

def fibonacci_reverse(n):
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [1, 0]
    else:
        fib = fibonacci_reverse(n - 1)
        fib.insert(0, fib[0] + fib[1])
        return fib

def create_app():
    app = Flask(__name__)
    app.config['DEBUG'] = True

    @app.route('/', methods=['GET', 'POST'])
    def fibonacci():
        result = []
        error = None
        if request.method == 'POST':
            try:
                num = request.form['number']
                if not re.match(r'^[0-9]+$', num):
                    error = 'Invalid Input! Please enter a non-negative integer.'
                elif int(num) < 1:
                    error = 'Invalid Input! Please enter a integer greater than 0.'
                else:
                    result = fibonacci_reverse(int(num))
            except Exception as e:
                error = str(e)
        return render_template('index.html', result=result, error=error)

    return app

if __name__ == "__main__":
    application = create_app()
    application.run()

