from functools import wraps
from flask import Flask, redirect, url_for, request
import flask_tasks

def create_app():
    app = Flask(__name__)

    class User:
        def __init__(self, username: str, password: str, role: str):
            self.username = username
            self.password = password
            self.role = role

    users = [User("admin", "123", "admin"),
             User("user1", "123", "member"),
             User("user2", "123", "guest")]

    def authenticate(username, password):
        for user in users:
            if user.username == username and user.password == password:
                return user
        return None

    def roles_required(*roles):
        def wrapper(func):
            @wraps(func)
            def decorated_view(*args, **kwargs):
                if not request.session.get('logged_in', False):
                    return "You need to login first", 401
                elif request.session['role'] not in roles:
                    return "You do not have access to this resource", 403
                return func(*args, **kwargs)
            return decorated_view
        return wrapper

    @app.route('/login', methods=['POST'])
    def login():
        user = authenticate(request.form['username'], request.form['password'])
        if user:
            request.session['logged_in'] = True
            request.session['role'] = user.role
            return redirect(url_for('home'))
        else:
            return "Invalid credentials", 401

    @app.route('/')
    @roles_required('admin', 'member')
    def home():
        return "You are in protected zone"

    return app

if __name__ == '__main__':
    create_app().run(debug=True)

