@weather_app.route('/api/weather/<city>', methods=['GET'])
def fetch_weather(city):
    api_url = f'http://api.openweathermap.org/data/2.5/forecast?q={city}&units=imperial&cnt=3&appid=your_api_key'
    resp = requests.get(api_url)
    data = resp.json()
    if resp.status_code == 200:
        forecast = []
        for i in range(3):
            info = data['list'][i]
            forecast.append({
                'date': info['dt_txt'],
                'temperature': info['main']['temp'],
                'description': info['weather'][0]['description']
            })
        return jsonify(forecast), 200
    else:
        return make_response(jsonify(data), resp.status_code)

