# --------------------------------------------------------------------------- #
# Helper: build_error_response
# --------------------------------------------------------------------------- #
def _build_error(code, short_msg, long_msg):
    """Construct a consistent error payload."""
    return HTTPError(code, data={
        'message_short': short_msg,
        'message_long': long_msg
    })


# --------------------------------------------------------------------------- #
# Decorator: must_be_signed
# --------------------------------------------------------------------------- #
def must_be_signed(func):
    """Validate HMAC signature and payload expiration."""
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        data = request.args if request.method in ('GET', 'DELETE') else request.get_json()

        try:
            sig = data['signature']
            payload = signing.unserialize_payload(data['payload'])
            exp = payload['time']
        except (KeyError, ValueError):
            raise _build_error(
                http_status.HTTP_400_BAD_REQUEST,
                'Invalid payload',
                'The request payload could not be deserialized.'
            )

        if not signing.default_signer.verify_payload(sig, payload):
            raise HTTPError(http_status.HTTP_401_UNAUTHORIZED)

        if time.time() > exp:
            raise _build_error(
                http_status.HTTP_400_BAD_REQUEST,
                'Expired',
                'Signature has expired.'
            )

        kwargs['payload'] = payload
        return func(*args, **kwargs)

    return wrapped


# --------------------------------------------------------------------------- #
# Decorator: block_bing_preview
# --------------------------------------------------------------------------- #
def block_bing_preview(func):
    """Block request from BingPreview or IE9."""
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        ua = request.headers.get('User-Agent')
        if ua and ('BingPreview' in ua or 'MSIE 9.0' in ua):
            msg = (
                f'Internet Explorer 9 and BingPreview cannot be used to access this page '
                f'for security reasons. Please use another browser. If this should not have '
                f'occurred and the issue persists, please report it to <a href="mailto: '
                f'{settings.OSF_SUPPORT_EMAIL}">{settings.OSF_SUPPORT_EMAIL}</a>.'
            )
            return HTTPError(http_status.HTTP_403_FORBIDDEN, data={'message_long': msg})
        return func(*args, **kwargs)

    return wrapped


# --------------------------------------------------------------------------- #
# Decorator: collect_auth
# --------------------------------------------------------------------------- #
def collect_auth(func):
    """Attach Auth object to the kwargs."""
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        kwargs['auth'] = Auth.from_kwargs(request.args.to_dict(), kwargs)
        return func(*args, **kwargs)

    return wrapped


# --------------------------------------------------------------------------- #
# Decorator: must_be_confirmed
# --------------------------------------------------------------------------- #
def must_be_confirmed(func):
    """Ensure the user identified by uid is confirmed."""
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        from osf.models import OSFUser

        user = OSFUser.load(kwargs['uid'])
        if user is None:
            raise HTTPError(http_status.HTTP_404_NOT_FOUND)

        if not user.is_confirmed:
            raise _build_error(
                http_status.HTTP_400_BAD_REQUEST,
                'Account not yet confirmed',
                'The profile page could not be displayed as the user has not confirmed the account.'
            )
        return func(*args, **kwargs)

    return wrapped


# --------------------------------------------------------------------------- #
# Decorator: must_be_logged_in
# --------------------------------------------------------------------------- #
def must_be_logged_in(func):
    """Require a logged‑in user, redirecting to CAS if absent."""
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        kwargs['auth'] = Auth.from_kwargs(request.args.to_dict(), kwargs)
        if not kwargs['auth'].logged_in:
            return redirect(cas.get_login_url(request.url))
        return func(*args, **kwargs)

    return wrapped

