import os
import zipfile
from flask import render_template, request
import flask_tasks


class ZipPreviewer:
    """ZIP previewer providing preview capability."""

    @staticmethod
    def _build_tree(archive_path):
        """Create tree structure from ZIP archive."""
        with zipfile.ZipFile(archive_path) as zf:
            root = {'type': 'folder', 'id': -1, 'children': {}}
            for i, info in enumerate(zf.infolist()):
                parts = info.filename.split(os.sep)
                node = root
                for part in parts:
                    if part not in node['children']:
                        if part == '':
                            node['type'] = 'folder'
                            continue
                        node['children'][part] = {
                            'name': part,
                            'type': 'item',
                            'id': f'item{i}',
                            'children': {}
                        }
                    node = node['children'][part]
                node['size'] = info.file_size
            return root

    @staticmethod
    def _list_children(node):
        """Organize children structure."""
        if node['type'] == 'item' and not node['children']:
            del node['children']
        else:
            node['type'] = 'folder'
            node['children'] = list(node['children'].values())
            node['children'].sort(key=lambda x: x['name'])
            node['children'] = map(ZipPreviewer._list_children, node['children'])
        return node

    @staticmethod
    def can_preview(f):
        """Return True if filetype can be previewed."""
        return f.superformat.lower() == '.zip'

    @staticmethod
    def preview(f):
        """Return appropriate template and pass the file and an embed flag."""
        tree_root = ZipPreviewer._list_children(
            ZipPreviewer._build_tree(f.get_full_path()))['children']
        return render_template(
            "previewer/zip.html",
            f=f,
            tree=tree_root,
            embed=request.args.get('embed', type=bool)
        )


def create_previewer():
    """Factory returning the ZipPreviewer class."""
    return ZipPreviewer

