from config import SECRET_KEY, PASSWORD_RESET_EMAIL
from datetime import datetime, timedelta
from functools import wraps
from flask import g, Blueprint, jsonify, make_response, request
import flask_tasks
from flask_restful import Resource, Api
import flask_restful
from flask_mail import Mail, Message
from werkzeug.security import check_password_hash, generate_password_hash
from sqlalchemy.exc import SQLAlchemyError
from marshmallow import ValidationError
import jwt
from jwt import DecodeError, ExpiredSignature
from app.base_model import db
from app.employees.models import Employee, EmployeeSchema

login_bp = Blueprint('login', __name__)
api = Api(login_bp)
schema = EmployeeSchema(strict=True)
mail = Mail()

def create_token(user):
    payload = {
        'sub': user.id,
        'iat': datetime.utcnow(),
        'exp': datetime.utcnow() + timedelta(days=1),
        'scope': 'emp'
    }
    token = jwt.encode(payload, SECRET_KEY)
    return token.decode('unicode_escape')

def parse_token(req):
    token = req.headers.get('Authorization').split()[1]
    return jwt.decode(token, SECRET_KEY, algorithms='HS256')

def login_required(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)
    return wrapper

def admin_login_required(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        if not request.headers.get('Authorization'):
            return jsonify(message='Missing authorization header'), 401
        try:
            payload = parse_token(request)
            if payload['scope'] != 'admin':
                return jsonify(error='Admin Access Required'), 401
        except DecodeError:
            return jsonify(message='Token is invalid'), 401
        except ExpiredSignature:
            return jsonify(message='Token has expired'), 401
        g.user_id = payload['sub']
        return f(*args, **kwargs)
    return wrapper

class ForgotPassword(Resource):
    def patch(self):
        if not request.headers.get('Authorization'):
            return jsonify(message='Missing authorization header'), 401
        try:
            payload = parse_token(request)
            user = Employee.query.get_or_404(payload['sub'])
            attrs = request.get_json(force=True)['data']['attributes']
            user.empPassword = generate_password_hash(attrs['password'])
            try:
                user.update()
                return {}, 201
            except SQLAlchemyError as e:
                db.session.rollback()
                return jsonify(error=str(e)), 401
        except DecodeError:
            return jsonify(message='Token is invalid'), 401
        except ExpiredSignature:
            return jsonify(message='Token has expired'), 401

    def post(self):
        attrs = request.get_json(force=True)['data']['attributes']
        user = Employee.query.filter_by(empEmail=attrs['email']).first()
        if user:
            token = create_token(user)
            msg = Message("Here's your Password Reset Link :)",
                          recipients=[attrs['email']])
            msg.html = PASSWORD_RESET_EMAIL.format(token=token)
            mail.send(msg)
            return {"message": "Password reset mail sent successfully"}, 201
        return {"error": "We could not find this email address :("}, 404

class Auth(Resource):
    def post(self):
        raw = request.get_json(force=True)
        attrs = raw['data']['attributes']
        user = Employee.query.filter_by(empEmail=attrs['email']).first()
        if not user or not check_password_hash(user.empPassword, attrs['password']):
            return jsonify(message="invalid username/password"), 401
        return {"token": create_token(user)}

class SignUp(Resource):
    def post(self):
        raw = request.get_json(force=True)
        try:
            schema.validate(raw)
            attrs = raw['data']['attributes']
            user = Employee(
                attrs['email'],
                generate_password_hash(attrs['password']),
                attrs['name'], attrs['name'])
            user.add(user)
            query = Employee.query.get(user.id)
            return schema.dump(query).data, 201
        except ValidationError as err:
            return jsonify(error=err.messages), 403
        except SQLAlchemyError as e:
            db.session.rollback()
            return jsonify(error=str(e)), 403

api.add_resource(ForgotPassword, 'forgotpassword')
api.add_resource(Auth, 'login.json')
api.add_resource(SignUp, 'signup.json')

