import os
import zipfile
from flask import render_template, request
import flask_tasks


def build_and_list_tree(archive_path):
    """Build a ZIP archive tree and convert children to a sorted list."""
    zf = zipfile.ZipFile(archive_path)
    root = {'type': 'folder', 'id': -1, 'children': {}}

    for i, info in enumerate(zf.infolist()):
        node = root
        for part in info.filename.split(os.sep):
            if part not in node['children']:
                if part:
                    node['children'][part] = {
                        'name': part,
                        'type': 'item',
                        'id': f'item{i}',
                        'children': {}
                    }
                else:
                    node['type'] = 'folder'
            node = node['children'][part]
        node['size'] = info.file_size

    def convert(node):
        if node['type'] == 'item' and not node['children']:
            del node['children']
        else:
            node['type'] = 'folder'
            children = list(node['children'].values())
            children.sort(key=lambda x: x['name'])
            node['children'] = list(map(convert, children))
        return node

    return convert(root)['children']


def can_preview(f):
    """Return True if filetype can be previewed."""
    return f.superformat.lower() == '.zip'


def preview(f):
    """Render the ZIP preview template with the constructed tree."""
    tree = build_and_list_tree(f.get_full_path())
    return render_template(
        "previewer/zip.html",
        f=f,
        tree=tree,
        embed=request.args.get('embed', type=bool)
    )

