from flask import g, Blueprint, request
import flask_tasks
from flask.ext.login import login_required, login_user

from social.actions import do_auth, do_complete, do_disconnect
from social.apps.flask_app.utils import psa


social_bp = Blueprint('social', __name__)


# Disconnect routes – first in the file for visibility
@social_bp.route('/disconnect/<string:backend>/', methods=('POST',))
@social_bp.route('/disconnect/<string:backend>/<int:association_id>/', methods=('POST',))
@social_bp.route('/disconnect/<string:backend>/<string:association_id>/', methods=('POST',))
@login_required
@psa()
def disconnect_view(backend, association_id=None):
    """Disconnects given backend from current logged in user."""
    return do_disconnect(g.backend, g.user, association_id)


# Login route
@social_bp.route('/login/<string:backend>/', methods=('GET', 'POST'))
@psa('social.complete')
def login_view(backend):
    return do_auth(g.backend)


# Complete route
@social_bp.route('/complete/<string:backend>/', methods=('GET', 'POST'))
@psa('social.complete')
def complete_view(backend, *args, **kwargs):
    """Authentication complete view, override this view if transaction
    management doesn't suit your needs."""
    return do_complete(g.backend, login=do_login, user=g.user,
                       *args, **kwargs)


def do_login(backend, user, social_user):
    name = backend.strategy.setting('REMEMBER_SESSION_NAME', 'keep')
    remember = backend.strategy.session_get(name) or \
               request.cookies.get(name) or \
               request.args.get(name) or \
               request.form.get(name) or \
               False
    return login_user(user, remember=remember)

