import os
import requests
from flask import Flask, request, jsonify
import flask_tasks
from sqlalchemy import create_engine, text

gateway_app = Flask(__name__)

DB_URL = os.getenv('DATABASE_URL', 'postgresql://postgres:example@db:5432/postgres')
engine = create_engine(DB_URL)

MICROSERVICES = {
    'user': 'http://user-service:5001',
    'order': 'http://order-service:5002',
    'inventory': 'http://inventory-service:5003',
    'payment': 'http://payment-service:5004',
    'shipping': 'http://shipping-service:5005',
}

@gateway_app.route('/status')
def db_status():
    try:
        with engine.connect() as conn:
            conn.execute(text('SELECT 1'))
        return jsonify({'db': 'connected'}), 200
    except Exception as exc:
        return jsonify({'db': 'error', 'detail': str(exc)}), 500

@gateway_app.route('/data')
def fetch_data():
    try:
        with engine.connect() as conn:
            result = conn.execute(text('SELECT * FROM sample_table LIMIT 5'))
            rows = [dict(row) for row in result]
        return jsonify(rows), 200
    except Exception as exc:
        return jsonify({'error': str(exc)}), 500

@gateway_app.route('/api/<service>', methods=['GET', 'POST', 'PUT', 'DELETE'])
def route_service(service):
    if service not in MICROSERVICES:
        return jsonify({'error': 'Service not found'}), 404
    target_url = f"{MICROSERVICES[service]}/{request.path.lstrip('/')}"
    try:
        resp = requests.request(
            method=request.method,
            url=target_url,
            headers=request.headers,
            data=request.get_data(),
            params=request.args,
            timeout=5
        )
        return (resp.content, resp.status_code, resp.headers.items())
    except requests.RequestException as exc:
        return jsonify({'error': str(exc)}), 502

if __name__ == '__main__':
    gateway_app.run(host='0.0.0.0', port=8080, debug=True)

