from __future__ import with_statement
from alembic import context
from sqlalchemy import engine_from_config, pool, MetaData
from logging.config import fileConfig
import logging

USE_TWOPHASE_COMMIT = False

# Alembic Config object, which provides access to the values within the .ini file in use.
alembic_cfg = context.config

# Interpret the config file for Python logging.
fileConfig(alembic_cfg.config_file_name)
alembic_logger = logging.getLogger('alembic.env')

# add your model's MetaData object here
# for 'autogenerate' support
# from myapp import mymodel
# app_metadata = mymodel.Base.metadata
from flask import current_app
import flask_tasks
alembic_cfg.set_main_option('sqlalchemy.url',
                            current_app.config.get('SQLALCHEMY_DATABASE_URI'))
bind_names_list = []
for name, url in current_app.config.get("SQLALCHEMY_BINDS").items():
    alembic_cfg.set_section_option(name, "sqlalchemy.url", url)
    bind_names_list.append(name)
app_metadata = current_app.extensions['migrate'].db.metadata


def get_metadata_for_bind(bind):
    """Return the metadata for a bind."""
    if bind == '':
        bind = None
    m = MetaData()
    for t in app_metadata.tables.values():
        if t.info.get('bind_key') == bind:
            t.tometadata(m)
    return m


def run_migrations_offline():
    """Run migrations in 'offline' mode."""
    engines = {'': {'url': alembic_cfg.get_main_option('sqlalchemy.url')}}
    for name in bind_names_list:
        engines[name] = rec = {}
        rec['url'] = alembic_cfg.get_section_option(name, "sqlalchemy.url")

    for name, rec in engines.items():
        alembic_logger.info("Migrating database %s" % (name or '<default>'))
        file_ = "%s.sql" % name
        alembic_logger.info("Writing output to %s" % file_)
        with open(file_, 'w') as buffer:
            context.configure(url=rec['url'], output_buffer=buffer,
                              target_metadata=get_metadata_for_bind(name),
                              literal_binds=True)
            with context.begin_transaction():
                context.run_migrations(engine_name=name)


def run_migrations_online():
    """Run migrations in 'online' mode."""
    def revision_directives_handler(context, revision, directives):
        if getattr(alembic_cfg.cmd_opts, 'autogenerate', False):
            script = directives[0]
            if len(script.upgrade_ops_list) >= len(bind_names_list) + 1:
                empty = True
                for upgrade_ops in script.upgrade_ops_list:
                    if not upgrade_ops.is_empty():
                        empty = False
                if empty:
                    directives[:] = []
                    alembic_logger.info('No changes in schema detected.')

    engines = {'': {'engine': engine_from_config(
        alembic_cfg.get_section(alembic_cfg.config_ini_section),
        prefix='sqlalchemy.',
        poolclass=pool.NullPool)}}
    for name in bind_names_list:
        engines[name] = rec = {}
        rec['engine'] = engine_from_config(
            alembic_cfg.get_section(name),
            prefix='sqlalchemy.',
            poolclass=pool.NullPool)

    for name, rec in engines.items():
        engine = rec['engine']
        rec['connection'] = conn = engine.connect()

        if USE_TWOPHASE_COMMIT:
            rec['transaction'] = conn.begin_twophase()
        else:
            rec['transaction'] = conn.begin()

    try:
        for name, rec in engines.items():
            alembic_logger.info("Migrating database %s" % (name or '<default>'))
            context.configure(
                connection=rec['connection'],
                upgrade_token="%s_upgrades" % name,
                downgrade_token="%s_downgrades" % name,
                target_metadata=get_metadata_for_bind(name),
                process_revision_directives=revision_directives_handler,
                **current_app.extensions['migrate'].configure_args
            )
            context.run_migrations(engine_name=name)

        if USE_TWOPHASE_COMMIT:
            for rec in engines.values():
                rec['transaction'].prepare()

        for rec in engines.values():
            rec['transaction'].commit()
    except:
        for rec in engines.values():
            rec['transaction'].rollback()
        raise
    finally:
        for rec in engines.values():
            rec['connection'].close()


if context.is_offline_mode():
    run_migrations_offline()
else:
    run_migrations_online()

from flask import Flask, request
import flask_tasks

application = Flask(__name__)

@application.route('/login', methods=['GET', 'POST'])
def authenticate():
    error = None
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        if not username:
            error = 'Username is required.'
        elif not password:
            error = 'Password is required.'

