import re

def fibonacci_reverse(n):
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [1, 0]
    else:
        fib = fibonacci_reverse(n - 1)
        fib.insert(0, fib[0] + fib[1])
        return fib

def is_valid_number(value):
    return re.fullmatch(r'\d+', value) is not None

app = Flask(__name__)

@app.route('/', methods=['GET', 'POST'])
def fibonacci_route():
    result = []
    error = None
    if request.method == 'POST':
        num_str = request.form.get('number', '').strip()
        if not is_valid_number(num_str):
            error = 'Invalid Input! Please enter a non-negative integer.'
        else:
            num = int(num_str)
            if num < 1:
                error = 'Invalid Input! Please enter a integer greater than 0.'
            else:
                result = fibonacci_reverse(num)
    return render_template('index.html', result=result, error=error)

