        @staticmethod
        def add(address: str) -> None:
            date = str(datetime.date.today())
            subscriber = Subscriber(email=address, datesubbed=date)
            db.session.add(subscriber)
            db.session.commit()

        @staticmethod
        def remove(address: str) -> None:
            subscriber = Subscriber.query.filter_by(email=address).first()
            if subscriber:
                db.session.delete(subscriber)
                db.session.commit()

        @staticmethod
        def list() -> str:
            subs = Subscriber.query.all()
            return ''.join(f"{s}<br/>" for s in subs)

    return Subscriber

