from flask import Flask, request, json
import flask_tasks

from virtual_box_tools.command_process import CommandFailed
from virtual_box_tools.virtual_box_tools import Commands
from virtual_box_tools.yaml_config import YamlConfig


def create_app() -> Flask:
    app = Flask(__name__)

    config = YamlConfig('~/.virtual-box-tools.yaml')
    token = config.get('token')
    sudo_user = config.get('sudo_user')
    listen_address = config.get('listen_address')

    def check_auth() -> str:
        header = str(request.headers.get('Authorization'))
        auth_type = ''
        auth_token = ''

        if header:
            parts = header.split(' ')
            if len(parts) == 2:
                auth_type, auth_token = parts

        return '' if auth_token == token and auth_type == 'Token' else 'Authorization failed.'

    def format_exception(exc: CommandFailed) -> str:
        return json.dumps(
            {
                'command': exc.get_command(),
                'standard_output': exc.get_standard_output(),
                'standard_error': exc.get_standard_error(),
                'return_code': exc.get_return_code()
            }
        )

    @app.route('/host', methods=['GET', 'POST'])
    @app.route('/host/<name>', methods=['GET', 'DELETE'])
    def host_endpoint(name: str = ''):
        if check_auth() != '':
            return 'Authorization failed.', 401

        commands = Commands(sudo_user)

        if request.method == 'GET':
            if name == '':
                try:
                    return json.dumps(commands.list_hosts())
                except CommandFailed as exc:
                    return format_exception(exc), 500
            else:
                try:
                    return json.dumps(commands.show_host(name=name))
                except CommandFailed as exc:
                    if 'Could not find a registered machine named' in exc.get_standard_error():
                        return json.dumps({'message': 'Host not found.'}), 404
                    return format_exception(exc), 500
        elif request.method == 'POST':
            try:
                return json.dumps(commands.create_host(str(request.json.get('name'))))
            except CommandFailed as exc:
                return format_exception(exc), 500
        elif request.method == 'DELETE':
            try:
                return json.dumps(commands.destroy_host(name))
            except CommandFailed as exc:
                return format_exception(exc), 500
        return 'Unexpected method: ' + request.method, 500

    app.config['LISTEN_ADDRESS'] = listen_address
    return app


app = create_app()


def main() -> int:
    app.run(host=app.config['LISTEN_ADDRESS'])
    return 0


if __name__ == '__main__':
    main()

