import logging
import binascii
import datetime
import base64

from flask_restful import reqparse, abort
import flask_restful
from flask import request, g
import flask_tasks
from functools import wraps
from jormungandr.exceptions import RegionNotFound
from navitiacommon.models import User, Instance, db, Key
from jormungandr import cache, app as flask_app


def extract_token():
    """
    Find the Token in the "Authorization" HTTP header.
    Handles two cases:
        - The token is the only value in the header.
        - Basic Authentication is used and the token is in the username part.
    """
    auth = None
    if 'Authorization' in request.headers:
        auth = request.headers['Authorization']
    elif 'key' in request.args:
        auth = request.args['key']
    if not auth:
        return None
    parts = auth.split(' ')
    if len(parts) == 2:
        b64 = parts[1]
        try:
            decoded = base64.decodestring(b64)
            return decoded.split(':')[0]
        except binascii.Error:
            logging.getLogger(__name__).info('badly formatted token %s', auth)
            flask_restful.abort(401, message="Unauthorized, invalid token", status=401)
            return None
    else:
        return auth


def auth_required(func):
    """
    Decorator handling authentication for every API that receives a region parameter.
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        region = None
        if 'region' in kwargs:
            region = kwargs['region']
        elif 'lon' in kwargs and 'lat' in kwargs:
            try:
                from jormungandr import i_manager
                region = i_manager.get_region(lon=kwargs['lon'], lat=kwargs['lat'])
            except RegionNotFound:
                pass
        elif flask_app.config.get('DEFAULT_REGION'):
            region = flask_app.config.get('DEFAULT_REGION')

        user = retrieve_user(token=extract_token())
        if not region:
            abort_request(user=user)

        if check_access(region, 'ALL', abort=True, user=user):
            return func(*args, **kwargs)
    return wrapper


@cache.memoize(flask_app.config['CACHE_CONFIGURATION'].get('TIMEOUT_AUTHENTICATION', 300))
def check_access(region, api, abort, user):
    """
    Verify the current user's authorization for the given region and API.
    """
    if flask_app.config.get('PUBLIC', False):
        return True

    if not user:
        abort_request(user=user)

    model_instance = Instance.get_by_name(region)
    if not model_instance:
        if abort:
            raise RegionNotFound(region)
        return False

    if (model_instance.is_free and user.have_access_to_free_instances) or user.has_access(model_instance.id, api):
        return True
    else:
        if abort:
            abort_request(user=user)
        else:
            return False


@cache.memoize(flask_app.config['CACHE_CONFIGURATION'].get('TIMEOUT_AUTHENTICATION', 300))
def cached_user(token):
    """
    Cached lookup of a User from a token.
    """
    return User.get_from_token(token, datetime.datetime.now())


@cache.memoize(flask_app.config['CACHE_CONFIGURATION'].get('TIMEOUT_AUTHENTICATION', 300))
def cached_key(token):
    """
    Cached lookup of a Key from a token.
    """
    return Key.get_by_token(token)


def retrieve_user(token, abort_if_no_token=True):
    """
    Return the authenticated User or None.
    """
    if hasattr(g, 'user'):
        return g.user
    if not token:
        if not flask_app.config.get('PUBLIC', False):
            if abort_if_no_token:
                flask_restful.abort(401, message='no token')
            else:
                return None
        else:
            g.user = User(login="unknown_user")
            g.user.id = 0
    else:
        g.user = cached_user(token)
    return g.user


def get_application_name(token):
    """
    Return the app_name for the token.
    """
    if token:
        key = cached_key(token)
        if key:
            return key.app_name
    return None


def abort_request(user=None):
    """
    Abort the request with the appropriate status if authentication fails.
    """
    if user:
        flask_restful.abort(403)
    else:
        flask_restful.abort(401)

