def flatten_line(line):
    return line['#text'] if isinstance(line, dict) else line

def load_odyssey(book=None, lines=None, lang="gk"):
    path = os.environ['HOMER_PATH']
    with open(f"{path}/hom.od_{lang}.xml.json") as fp:
        odyssey_dict = json.load(fp)

    res = odyssey_dict['TEI.2']['text']['body']['div1']

    if lang == "gk":
        if book and lines:
            return flatten_line([res[book - 1]['l'][line]])
        elif book:
            return [parse_beta(flatten_line(x).upper()) for x in res[book - 1]['l']]
        else:
            return res
    return res[book - 1]['p']['#text']

def handle_post_interactions():
    data = request.get_json()
    interaction = db.create_interaction(
        typee=data["type"],
        fromm=data["from"],
        to=data["to"],
        sel=data["selection"],
        book=int(data["book"])
    )
    return make_response(json.dumps(interaction._store), 200)

def handle_get_interactions():
    book = request.args.get("book")
    book = int(book) if book is not None else None
    interactions = db.fetch_interactions(book=book)
    cleaned = []
    for x in interactions:
        x.pop('_key', None)
        x.pop('_rev', None)
        x['selection'].pop('from_offset', None)
        x['selection'].pop('to_offset', None)
        x['_id'] = x['_id'].replace('Interactions/', '')
        x['_from'] = x['_from'].replace('Entities/', '')
        x['_to'] = x['_to'].replace('Entities/', '')
        cleaned.append(x)
    return make_response(json.dumps(cleaned), 200)

def handle_post_entities():
    data = request.get_json()
    entity = db.create_entity(
        name=data["name"],
        metadata=data["metadata"],
        typee=data["type"]
    )
    return make_response(json.dumps(entity._store), 200)

def handle_get_entities():
    entities = db.db["Entities"].fetchAll(rawResults=True)
    cleaned = []
    for x in entities:
        x['_id'] = x['_id'].replace('Entities/', '')
        cleaned.append(x)
    return make_response(json.dumps(cleaned), 200)

