application = Flask(__name__)

def testPlanOutScript(script, inputs={}, overrides=None, assertions=None):
    payload = {}
    i = Interpreter(script, 'demo_salt', inputs)
    if overrides:
        i.set_overrides(overrides)
    try:
        results = dict(i.get_params())
    except Exception as err:
        payload['errors'] = [
            {"error_code": "runtime", "message": str(err)}
        ]
        return payload
    payload['results'] = results
    if assertions:
        validation_errors = []
        for key, value in assertions.items():
            if key not in results or results[key] != value:
                validation_errors.append(
                    {"error_code": "assertion", "message": {"param": key}}
                )
        if validation_errors:
            payload['errors'] = validation_errors
    return payload

