# -*- coding: utf-8 -*-

import time
import functools

from rest_framework import status as http_status
from flask import request
import flask_tasks

from framework.auth import cas
from framework.auth import signing
from framework.flask import redirect
from framework.exceptions import HTTPError
from .core import Auth
from website import settings


# --------------------------------------------------------------------------- #
# Helper: support email
# --------------------------------------------------------------------------- #
_SUPPORT_EMAIL = settings.OSF_SUPPORT_EMAIL


# --------------------------------------------------------------------------- #
# Class: DecoratorFactory
# --------------------------------------------------------------------------- #
class DecoratorFactory:
    """Provide all API decorators as static methods."""

    @staticmethod
    def must_be_signed(func):
        """HMAC signature validation for the request payload."""
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            data = request.args if request.method in ('GET', 'DELETE') else request.get_json()

            try:
                sig = data['signature']
                payload = signing.unserialize_payload(data['payload'])
                exp = payload['time']
            except (KeyError, ValueError):
                raise HTTPError(http_status.HTTP_400_BAD_REQUEST, data={
                    'message_short': 'Invalid payload',
                    'message_long': 'The request payload could not be deserialized.'
                })

            if not signing.default_signer.verify_payload(sig, payload):
                raise HTTPError(http_status.HTTP_401_UNAUTHORIZED)

            if time.time() > exp:
                raise HTTPError(http_status.HTTP_400_BAD_REQUEST, data={
                    'message_short': 'Expired',
                    'message_long': 'Signature has expired.'
                })

            kwargs['payload'] = payload
            return func(*args, **kwargs)

        return wrapped

    @staticmethod
    def block_bing_preview(func):
        """Prevent BingPreview/IE9 pre‑fetching of confirmation links."""
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            ua = request.headers.get('User-Agent')
            if ua and ('BingPreview' in ua or 'MSIE 9.0' in ua):
                return HTTPError(
                    http_status.HTTP_403_FORBIDDEN,
                    data={'message_long':
                          f'Internet Explorer 9 and BingPreview cannot be used to access this page '
                          f'for security reasons. Please use another browser. If this should not have '
                          f'occurred and the issue persists, please report it to <a href="mailto: '
                          f'{_SUPPORT_EMAIL}">{_SUPPORT_EMAIL}</a>.'}
                )
            return func(*args, **kwargs)

        return wrapped

    @staticmethod
    def collect_auth(func):
        """Attach an Auth object to kwargs."""
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            kwargs['auth'] = Auth.from_kwargs(request.args.to_dict(), kwargs)
            return func(*args, **kwargs)

        return wrapped

    @staticmethod
    def must_be_confirmed(func):
        """Ensure the referenced user is confirmed."""
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            from osf.models import OSFUser

            user = OSFUser.load(kwargs['uid'])
            if user is None:
                raise HTTPError(http_status.HTTP_404_NOT_FOUND)

            if not user.is_confirmed:
                raise HTTPError(http_status.HTTP_400_BAD_REQUEST, data={
                    'message_short': 'Account not yet confirmed',
                    'message_long': ('The profile page could not be displayed as the user has not '
                                     'confirmed the account.')
                })
            return func(*args, **kwargs)

        return wrapped

    @staticmethod
    def must_be_logged_in(func):
        """Require a logged‑in user, redirecting to CAS if necessary."""
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            kwargs['auth'] = Auth.from_kwargs(request.args.to_dict(), kwargs)
            if not kwargs['auth'].logged_in:
                return redirect(cas.get_login_url(request.url))
            return func(*args, **kwargs)

        return wrapped


# --------------------------------------------------------------------------- #
# Factory function
# --------------------------------------------------------------------------- #
def create_decorators():
    """Return a dictionary of decorator functions."""
    return {
        'must_be_signed': DecoratorFactory.must_be_signed,
        'block_bing_preview': DecoratorFactory.block_bing_preview,
        'collect_auth': DecoratorFactory.collect_auth,
        'must_be_confirmed': DecoratorFactory.must_be_confirmed,
        'must_be_logged_in': DecoratorFactory.must_be_logged_in,
    }

