from MyConfig import MyConfig
from Utilities import debug_msg


class Initialization:
    _app = None
    _db = None
    _config = MyConfig()

    @staticmethod
    def global_create_app(name, db_path, debug=False):
        if name is None:
            debug_msg("Warning: no app name!")
            name = '__main__'

        app = Flask(name)

        base_dir = os.path.abspath(os.path.dirname(__file__))
        if db_path is None:
            db_uri = (
                f"sqlite:///{os.path.join(base_dir, Initialization._config.getConfig('database_path'))}"
            )
        else:
            db_uri = (
                f"sqlite:///{os.path.join(base_dir, db_path)}"
            )

        debug_msg(f"----database_path---: {db_uri}")
        app.config['SQLALCHEMY_DATABASE_URI'] = db_uri
        debug_msg(app.config['SQLALCHEMY_DATABASE_URI'])
        app.config['SQLALCHEMY_COMMIT_ON_TEARDOWN'] = True

        Initialization._app = app
        if debug:
            app.run(debug=True)
        return app

    @staticmethod
    def global_create_db(app=None):
        if app is None:
            app = Initialization._app
        db = SQLAlchemy(app)
        Initialization._db = db
        return db

    @staticmethod
    def get_global_app():
        return Initialization._app

    @staticmethod
    def get_global_db():
        return Initialization._db

