from flask import Flask, request, jsonify
import flask_tasks
from flask_caching import Cache
import time

def create_app():
    """Factory that creates and configures the Flask application."""
    flask_app = Flask(__name__)

    # Inline Cache configuration
    Cache(flask_app, config={
        'CACHE_TYPE': 'redis',
        'CACHE_REDIS_URL': 'redis://localhost:6379/0'
    })

    @flask_app.route('/')
    def home():
        return "Hello, World!"

    @flask_app.route('/time-intensive')
    @Cache.memoize(timeout=50)
    def heavy_func():
        time.sleep(10)
        return 'Done!'

    @flask_app.route('/clear_cache')
    def clear_cache():
        Cache.delete_memoized(heavy_func)
        return 'Cache cleared!'

    @flask_app.route('/data/<id>')
    @Cache.cached(timeout=50, make_cache_key=lambda: make_cache_key())
    def pull_data(id):
        time.sleep(5)
        return jsonify({'id': id, 'data': f'Data for {id}'})

    def make_cache_key():
        path = request.path
        args_hash = str(hash(frozenset(request.args.items())))
        return f'{path}_{args_hash}'.encode('utf-8')

    return flask_app

if __name__ == '__main__':
    app = create_app()
    app.run(host='0.0.0.0', port=5000, debug=True)

