from flask import g
import flask_tasks
from meerkat_libs.auth_client import Authorise as libs_auth
from .app import app
from .messages import messages


class Authorise(libs_auth):
    """
    Extension of the meerkat_libs auth_client Authorise class.
    Overrides check_auth for location‑based access control.
    """

    def check_auth(self, access, countries, logic='OR'):
        libs_auth.check_auth(self, access, countries, logic)

        config = app.config
        allowed_location = 9999

        for level, loc in config.get('LOCATION_AUTH', {}).items():
            access = Authorise.check_access(
                [level],
                [config['COUNTRY']],
                g.payload['acc']
            )
            if access and loc < allowed_location:
                allowed_location = loc

        if allowed_location is 9999:
            allowed_location = 1

        g.allowed_location = allowed_location

        if config.get('CONFIG_OVERRIDES', {}):
            for level in reversed(g.payload['acc'][config['COUNTRY']]):
                if level in config.get('CONFIG_OVERRIDES', {}):
                    for k, v in config['COMPONENT_CONFIGS'].items():
                        g.config[k] = {
                            **config[k],
                            **config['CONFIG_OVERRIDES'][level]
                        }

        messages.flash()


def create_authorise(app_instance):
    return Authorise()


auth = create_authorise(app)

