"""Delete cascading system with modular helper functions."""

from eve.methods.delete import deleteitem_internal
from eve.methods.patch import patch_internal
from flask import current_app
import flask_tasks
from werkzeug.exceptions import NotFound

from amivapi.utils import admin_permissions


def _process_reference(res, field, data_relation, lookup):
    """Delete or nullify a referenced item depending on cascade flag."""
    with admin_permissions():
        try:
            if data_relation.get('cascade_delete'):
                deleteitem_internal(
                    res, concurrency_check=False, **lookup
                )
            else:
                patch_internal(
                    res, payload={field: None},
                    concurrency_check=False, **lookup
                )
        except NotFound:
            pass


def _handle_cascade_for_item(resource, item):
    """Cascade delete logic for a single deleted item."""
    domain = current_app.config['DOMAIN']
    deleted_id = item[domain[resource]['id_field']]

    for res, res_domain in domain.items():
        for field, data_relation in (
            (f, f_def['data_relation'])
            for f, f_def in res_domain['schema'].items()
            if 'data_relation' in f_def and
            f_def['data_relation'].get('resource') == resource
        ):
            lookup = {field: deleted_id}
            _process_reference(res, field, data_relation, lookup)


def _cascade_collection(resource, items):
    """Apply cascade logic to each item in a collection."""
    for itm in items:
        _handle_cascade_for_item(resource, itm)


def add_cascade_hooks(app):
    """Register cascade delete hooks with the given app."""
    app.on_deleted_item += _handle_cascade_for_item
    app.on_deleted += _cascade_collection

