from flask import Flask, jsonify, request
import flask_tasks
from flask_sqlalchemy import SQLAlchemy

flask_app = Flask(__name__)
flask_app.config['SQLALCHEMY_DATABASE_URI'] = 'postgresql://localhost/studentsdb'
db = SQLAlchemy(flask_app)

class Student(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(50), nullable=False)
    age = db.Column(db.Integer, nullable=False)
    course = db.Column(db.String(50), nullable=False)

    def as_dict(self):
        return {'id': self.id, 'name': self.name, 'age': self.age, 'course': self.course}

@flask_app.route('/students', methods=['GET'])
def students_handler():
    course_filter = request.args.get('course')
    sort_by_age = request.args.get('sort_by_age')

    query = db.session.query(Student)

    if course_filter:
        query = query.filter(Student.course == course_filter)

    if sort_by_age:
        query = query.order_by(Student.age if sort_by_age.lower() == 'asc' else -Student.age)

    students = query.all()
    return jsonify([student.as_dict() for student in students])

if __name__ == '__main__':
    flask_app.run()

from flask import Blueprint, request, jsonify
import flask_tasks
from ...middlewares import auth_manager
from .middlewares import (s, validate)
from ...container import container
from ...models import Device
from structlog import get_logger
from .view_models import Device as DeviceViewModel

logger = get_logger()

devices = Blueprint('devices', __name__, url_prefix='/devices')


@devices.route('', methods=['GET'])
@s(auth_manager)
def index():
    devices_list = container.account.devices.all()
    return dict(devices=devices_list)


@devices.route('', methods=['POST'])
@s(auth_manager, validate('device_create'))
def create():
    device = Device()
    device.name = request.data.name
    container.account.devices.append(device)
    container.database.commit()
    return dict(device=DeviceViewModel.from_device(device)), 204


@devices.route('/<int:id>', methods=['GET'])
@s(auth_manager)
def view(id):
    device = container.account.devices.first(id=id)
    if not device:
        return dict(), 404
    return dict(device=DeviceViewModel.from_device(device))


@devices.route('/<int:id>', methods=['PUT', 'DELETE'])
@s(auth_manager, validate('device_update') if request.method == 'PUT' else None)
def modify(id):
    device = container.account.devices.filter_by(id=id).first()
    if not device or device.is_deleted:
        return dict(), 404

    if request.method == 'PUT':
        device.name = request.data.name
        device.door_id = request.data.door_id
        container.database.commit()
        return dict(device=DeviceViewModel.from_device(device))

    if request.method == 'DELETE':
        device.is_deleted = True
        container.database.commit()
        return dict(), 200
